  TF_ENABLE_POOLABLE_ON_THIS;
#endif

  using Placeholder = std::monostate;

  struct Static {
    template <typename C>
    Static(C&&);
    std::function<void()> work;
  };

  struct Runtime {
    template <typename C>
    Runtime(C&&);
    std::function<void(tf::Runtime&)> work;
  };

  struct NonpreemptiveRuntime {

    template <typename C>
    NonpreemptiveRuntime(C&&);

    std::function<void(tf::NonpreemptiveRuntime&)> work;
  };

  struct Subflow {
    template <typename C>
    Subflow(C&&);
    std::function<void(tf::Subflow&)> work;
    Graph subgraph;
  };

  struct Condition {
    template <typename C>
    Condition(C&&);
    std::function<int()> work;
  };

  struct MultiCondition {
    template <typename C>
    MultiCondition(C&&);
    std::function<SmallVector<int>()> work;
  };

  struct Module {
    template <typename T>
    Module(T&);
    Graph& graph;
  };

  struct Async {
    template <typename T>
    Async(T&&);
    std::variant<
      std::function<void()>, 
      std::function<void(tf::Runtime&)>,
      std::function<void(tf::Runtime&, bool)>
    > work;
  };

  struct DependentAsync {

    template <typename C>
    DependentAsync(C&&);

    std::variant<
      std::function<void()>, 
      std::function<void(tf::Runtime&)>,
      std::function<void(tf::Runtime&, bool)>
    > work;

    std::atomic<size_t> use_count {1};
  };

  using handle_t = std::variant<
    Placeholder,
    Static,
    Runtime,
    NonpreemptiveRuntime,
    Subflow,
    Condition,
    MultiCondition,
    Module,
    Async,
    DependentAsync
  >;

  struct Semaphores {
    SmallVector<Semaphore*> to_acquire;
    SmallVector<Semaphore*> to_release;
  };

  public:

  constexpr static auto PLACEHOLDER           = get_index_v<Placeholder, handle_t>;
  constexpr static auto STATIC                = get_index_v<Static, handle_t>;
  constexpr static auto RUNTIME               = get_index_v<Runtime, handle_t>;
  constexpr static auto NONPREEMPTIVE_RUNTIME = get_index_v<NonpreemptiveRuntime, handle_t>;
  constexpr static auto SUBFLOW               = get_index_v<Subflow, handle_t>;
  constexpr static auto CONDITION             = get_index_v<Condition, handle_t>;
  constexpr static auto MULTI_CONDITION       = get_index_v<MultiCondition, handle_t>;
  constexpr static auto MODULE                = get_index_v<Module, handle_t>;
  constexpr static auto ASYNC                 = get_index_v<Async, handle_t>;
  constexpr static auto DEPENDENT_ASYNC       = get_index_v<DependentAsync, handle_t>;

  Node() = default;

  template <typename... Args>
  Node(nstate_t, estate_t, const TaskParams&, Topology*, NodeBase*, size_t, Args&&...);

  template <typename... Args>
  Node(nstate_t, estate_t, const DefaultTaskParams&, Topology*, NodeBase*, size_t, Args&&...);

  size_t num_successors() const;
  size_t num_predecessors() const;
  size_t num_strong_dependencies() const;
  size_t num_weak_dependencies() const;

  const std::string& name() const;

  private:

  std::string _name;

  void* _data {nullptr};

  Topology* _topology {nullptr};

  size_t _num_successors {0};
  SmallVector<Node*, 4> _edges;

  handle_t _handle;

  std::unique_ptr<Semaphores> _semaphores;

  bool _is_parent_cancelled() const;
  bool _is_conditioner() const;
  bool _acquire_all(SmallVector<Node*>&);
  void _release_all(SmallVector<Node*>&);
  void _precede(Node*);
  void _set_up_join_counter();

  void _remove_successors(Node*);
  void _remove_predecessors(Node*);

  std::atomic<size_t>& _root_join_counter();
};

// inline definitions for ctors/methods are provided later in the header.

class ExplicitAnchorGuard {

  public:

  ExplicitAnchorGuard(NodeBase* node_base) : _node_base{node_base} { 
    _node_base->_estate.fetch_or(ESTATE::EXPLICITLY_ANCHORED, std::memory_order_relaxed);
  }

  ~ExplicitAnchorGuard() {
    _node_base->_estate.fetch_and(~ESTATE::EXPLICITLY_ANCHORED, std::memory_order_relaxed);
  }

  private:

  NodeBase* _node_base;
};

class TaskGroup {

  friend class Executor;

  public:

  // ----------------------------------------------------------------------------------------------
  // deleted members
  // ----------------------------------------------------------------------------------------------

  /**
  @brief disabled copy constructor
  */
  TaskGroup(const TaskGroup&) = delete;

  /**
  @brief disabled move constructor
  */
  TaskGroup(TaskGroup&&) = delete;

  /**
  @brief disabled copy assignment
  */
  TaskGroup& operator = (TaskGroup&&) = delete;

  /**
  @brief disabled move assignment
  */
  TaskGroup& operator = (const TaskGroup&) = delete;

  /**
  @brief obtains the executor that creates this task group

  The running executor of a task group is the executor that creates the task group.

  @code{.cpp}
  executor.silent_async([&](){
    tf::TaskGroup tg = executor.task_group();
    assert(&(tg.executor()) == &executor);
  });
  @endcode
  */
  Executor& executor();

  // ----------------------------------------------------------------------------------------------
  // async methods
  // ----------------------------------------------------------------------------------------------

  template <typename F>
  auto async(F&& f);

  template <typename P, typename F>
  auto async(P&& params, F&& f);

  // ----------------------------------------------------------------------------------------------
  // silent async methods
  // ----------------------------------------------------------------------------------------------

  template <typename F>
  void silent_async(F&& f);

  template <typename P, typename F>
  void silent_async(P&& params, F&& f);

  // ----------------------------------------------------------------------------------------------
  // dependent async methods
  // ----------------------------------------------------------------------------------------------

  template <typename F, typename... Tasks,
    std::enable_if_t<all_same_v<AsyncTask, std::decay_t<Tasks>...>, void>* = nullptr
  >
  auto dependent_async(F&& func, Tasks&&... tasks);

  template <typename P, typename F, typename... Tasks,
    std::enable_if_t<is_task_params_v<P> && all_same_v<AsyncTask, std::decay_t<Tasks>...>, void>* = nullptr
  >
  auto dependent_async(P&& params, F&& func, Tasks&&... tasks);

  template <typename F, typename I,
    std::enable_if_t<!std::is_same_v<std::decay_t<I>, AsyncTask>, void>* = nullptr
  >
  auto dependent_async(F&& func, I first, I last);

  template <typename P, typename F, typename I,
    std::enable_if_t<is_task_params_v<P> && !std::is_same_v<std::decay_t<I>, AsyncTask>, void>* = nullptr
  >
  auto dependent_async(P&& params, F&& func, I first, I last);


  // ----------------------------------------------------------------------------------------------
  // silent dependent async methods
  // ----------------------------------------------------------------------------------------------

  template <typename F, typename... Tasks,
    std::enable_if_t<all_same_v<AsyncTask, std::decay_t<Tasks>...>, void>* = nullptr
  >
  tf::AsyncTask silent_dependent_async(F&& func, Tasks&&... tasks);

  template <typename P, typename F, typename... Tasks,
    std::enable_if_t<is_task_params_v<P> && all_same_v<AsyncTask, std::decay_t<Tasks>...>, void>* = nullptr
  >
  tf::AsyncTask silent_dependent_async(P&& params, F&& func, Tasks&&... tasks);

  template <typename F, typename I, 
    std::enable_if_t<!std::is_same_v<std::decay_t<I>, AsyncTask>, void>* = nullptr
  >
  tf::AsyncTask silent_dependent_async(F&& func, I first, I last);

  template <typename P, typename F, typename I, 
    std::enable_if_t<is_task_params_v<P> && !std::is_same_v<std::decay_t<I>, AsyncTask>, void>* = nullptr
  >
  tf::AsyncTask silent_dependent_async(P&& params, F&& func, I first, I last);


  // ----------------------------------------------------------------------------------------------
  // cooperative execution methods
  // ----------------------------------------------------------------------------------------------

  void corun();

  void cancel();

  bool is_cancelled();

  size_t size() const;

  private:

  explicit TaskGroup(Executor&, Worker&);

  Executor& _executor;

  Worker& _worker;

  NodeBase _node_base;
};

inline TaskGroup::TaskGroup(Executor& executor, Worker& worker) : 
  _executor  {executor}, 
  _worker    {worker}, 
  _node_base {NSTATE::IMPLICITLY_ANCHORED, ESTATE::NONE, nullptr, 0} {
}

inline Executor& TaskGroup::executor() {
  return _executor;
}

inline void TaskGroup::corun() {
  {
    ExplicitAnchorGuard anchor(&_node_base);
    _executor._corun_until(_worker, [this] () -> bool {
      return _node_base._join_counter.load(std::memory_order_acquire) == 0;
    });
  }
  _node_base._rethrow_exception();
}

inline void TaskGroup::cancel() {
  _node_base._estate.fetch_or(ESTATE::CANCELLED, std::memory_order_relaxed);
}

inline bool TaskGroup::is_cancelled() { 
  return _node_base._estate.load(std::memory_order_relaxed) & ESTATE::CANCELLED;
}

inline size_t TaskGroup::size() const {
  return _node_base._join_counter.load(std::memory_order_relaxed);
}

template <typename F>
void TaskGroup::silent_async(F&& f) {
  silent_async(DefaultTaskParams{}, std::forward<F>(f));
}

template <typename P, typename F>
void TaskGroup::silent_async(P&& params, F&& f) {
  _node_base._join_counter.fetch_add(1, std::memory_order_relaxed);
  _executor._silent_async(
    std::forward<P>(params), std::forward<F>(f), nullptr, &_node_base
  );
}

template <typename F>
auto TaskGroup::async(F&& f) {
  return async(DefaultTaskParams{}, std::forward<F>(f));
}

template <typename P, typename F>
auto TaskGroup::async(P&& params, F&& f) {
  _node_base._join_counter.fetch_add(1, std::memory_order_relaxed);
  return _executor._async(
    std::forward<P>(params), std::forward<F>(f), nullptr, &_node_base
  );
}

template <typename F, typename... Tasks,
  std::enable_if_t<all_same_v<AsyncTask, std::decay_t<Tasks>...>, void>*
>
tf::AsyncTask TaskGroup::silent_dependent_async(F&& func, Tasks&&... tasks) {
  return silent_dependent_async(
    DefaultTaskParams{}, std::forward<F>(func), std::forward<Tasks>(tasks)...
  );
}

template <typename P, typename F, typename... Tasks,
