class AsyncTask {

  friend class Executor;

  public:

    /**
    @brief constructs an empty task handle
    */
    AsyncTask() = default;

    /**
    @brief destroys the managed dependent-async task if this is the last owner
    */
    ~AsyncTask();

    /**
    @brief constructs a dependent-async task that shares ownership of @c rhs
    */
    AsyncTask(const AsyncTask& rhs);

    /**
    @brief move-constructs an dependent-async task from @c rhs
    */
    AsyncTask(AsyncTask&& rhs);

    /**
    @brief copy-assigns the dependent-async task from @c rhs

    Releases the managed object of @c this and retains a new shared ownership
    of @c rhs.
    */
    AsyncTask& operator = (const AsyncTask& rhs);

    /**
    @brief move-assigns the dependent-async task from @c rhs

    Releases the managed object of @c this and takes over the ownership of @c rhs.
    */
    AsyncTask& operator = (AsyncTask&& rhs);

    /**
    @brief checks if this dependent-async task is associated with any task

    An empty dependent-async task is not associated with any task created 
    from the executor.

    @code{.cpp}
    tf::AsyncTask task;
    assert(task.empty());
    @endcode
    */
    bool empty() const;

    /**
    @brief release the managed object of @c this

    Releases the ownership of the managed task, if any. 
    After the call `*this` manages no task.

    @code{.cpp}
    tf::AsyncTask task = executor.silent_dependent_async([](){});
    assert(task.empty() == false);
    task.reset();
    assert(task.empty() == true);
    @endcode
    */
    void reset();

    /**
    @brief obtains the hashed value of this dependent-async task

    @code{.cpp}
    tf::AsyncTask task = executor.silent_dependent_async([](){});
    std::cout << task.hash_value() << '\n';
    @endcode
    */
    size_t hash_value() const;

    /**
    @brief returns the number of shared owners that are currently managing 
           this dependent-async task

    In a multithreaded environment, `use_count` atomically retrieves 
    (with `memory_order_relaxed` load) the number of tf::AsyncTask instances that manage 
    the current task.

    @code{.cpp}
    tf::AsyncTask task;
    assert(task.use_count() == 0);
    @endcode
    */
    size_t use_count() const;

    /**                                                                                                       
    @brief checks if this dependent-async task finishes

    In a multithreaded environment, `is_done` atomically retrieves 
    (with `memory_order_acquire` load) the underlying state bit that indicates
    the completion of this dependent-async task.
    If the dependent-async task is empty, returns `true`.

    @code{.cpp}
    tf::AsyncTask task = executor.silent_dependent_async([](){});
    while(task.is_done() == false);
    std::cout << "dependent-async task finishes\n";

    task.reset();
    assert(task.is_done() == true);
    @endcode

    */
    bool is_done() const; 

    /**
    @brief retrieves the exception pointer of this task

    This method retrieves the exception pointer of the task, if any, that was silently caught by the executor. 
    For example, the code below retrieves the exception pointer of a dependent-async task that does not have 
    a shared state to propagate its exception. 

    @code{.cpp}
    tf::AsyncTask task = executor.silent_dependent_async([&](){
      throw std::runtime_error("oops"); 
    });
    executor.wait_for_all();

    // propagate the exception to the outer caller
    assert(task.exception_ptr() != nullptr);
    std::rethrow_exception(task.exception_ptr());
    @endcode

    */
    std::exception_ptr exception_ptr() const;

    /**
    @brief queries if the task has an exception pointer

    The method checks whether the task holds a pointer to a silently caught exception.
    */
    bool has_exception_ptr() const;

  private:

    explicit AsyncTask(Node*);

    Node* _node {nullptr};

    void _incref();
    void _decref();
};

// Constructor
inline AsyncTask::AsyncTask(Node* ptr) : _node{ptr} {
  _incref();
}

// Function: _incref
inline void AsyncTask::_incref() {
  if(_node) {
    std::get_if<Node::DependentAsync>(&(_node->_handle))->use_count.fetch_add(
      1, std::memory_order_relaxed
    );
  }
}

// Function: _decref
inline void AsyncTask::_decref() {
  if(_node && std::get_if<Node::DependentAsync>(&(_node->_handle))->use_count.fetch_sub(
      1, std::memory_order_acq_rel
    ) == 1) {
    recycle(_node);
  }
}

// Copy Constructor
inline AsyncTask::AsyncTask(const AsyncTask& rhs) : 
  _node{rhs._node} {
  _incref();
}

// Move Constructor
inline AsyncTask::AsyncTask(AsyncTask&& rhs) :
  _node {rhs._node} {
  rhs._node = nullptr;
}

// Destructor
inline AsyncTask::~AsyncTask() {
  _decref();
}

// Copy assignment
inline AsyncTask& AsyncTask::operator = (const AsyncTask& rhs) {
  _decref();
  _node = rhs._node;
  _incref();
  return *this;
}

// Move assignment
inline AsyncTask& AsyncTask::operator = (AsyncTask&& rhs) {
  _decref();
  _node = rhs._node;
  rhs._node = nullptr;
  return *this;
}

// Function: exception
inline std::exception_ptr AsyncTask::exception_ptr() const {
  return _node ? _node->_exception_ptr : nullptr;
}

// Function: has_exception
inline bool AsyncTask::has_exception_ptr() const {
  return _node ? (_node->_exception_ptr != nullptr) : false;
}

// Function: empty
inline bool AsyncTask::empty() const {
  return _node == nullptr;
}

// Function: reset
inline void AsyncTask::reset() {
  _decref();
  _node = nullptr;
}

// Function: hash_value
inline size_t AsyncTask::hash_value() const {
  return std::hash<Node*>{}(_node);
}

// Function: use_count
inline size_t AsyncTask::use_count() const {
  return _node == nullptr ? size_t{0} : 
  std::get_if<Node::DependentAsync>(&(_node->_handle))->use_count.load(
    std::memory_order_relaxed
  );
}

// Function: is_done
inline bool AsyncTask::is_done() const {
  return _node == nullptr ? true: (_node->_estate.load(std::memory_order_acquire) & ESTATE::FINISHED);
}

class Semaphore {

  friend class Node;
  friend class Executor;

  public:

    /**
    @brief constructs a default semaphore

    A default semaphore has the value of zero. Users can call tf::Semaphore::reset
    to reassign a new value to the semaphore.
    */
    Semaphore() = default;

    /**
    @brief constructs a semaphore with the given value (i.e., counter)

    A semaphore creates a constraint that limits the maximum concurrency,
    i.e., the number of workers, in a set of tasks.

    @code{.cpp}
    tf::Semaphore semaphore(4);  // concurrency constraint of 4 workers
    @endcode
    */
    explicit Semaphore(size_t max_value);

    /**
    @brief queries the current counter value
    */
    size_t value() const;

    /**
    @brief queries the maximum allowable value of this semaphore
    */
    size_t max_value() const;

    /**
    @brief resets the semaphores to a clean state
    */
    void reset();

    /**
    @brief resets the semaphores to a clean state with the given new maximum value
    */
    void reset(size_t new_max_value);

  private:

    mutable std::mutex _mtx;

    size_t _max_value{0};
    size_t _cur_value{0};

    SmallVector<Node*> _waiters;

    bool _try_acquire_or_wait(Node*);

    void _release(SmallVector<Node*>&);
};

inline Semaphore::Semaphore(size_t max_value) :
  _max_value(max_value),
  _cur_value(max_value) {
}

inline bool Semaphore::_try_acquire_or_wait(Node* me) {
  std::lock_guard<std::mutex> lock(_mtx);
  if(_cur_value > 0) {
    --_cur_value;
    return true;
  }
  else {
    _waiters.push_back(me);
    return false;
  }
}

inline void Semaphore::_release(SmallVector<Node*>& dst) {

  std::lock_guard<std::mutex> lock(_mtx);

  if(_cur_value >= _max_value) {
    TF_THROW("can't release the semaphore more than its maximum value: ", _max_value);
  }

  ++_cur_value;

  if(dst.empty()) {
    dst.swap(_waiters);
  }
  else {
    dst.reserve(dst.size() + _waiters.size());
    dst.insert(dst.end(), _waiters.begin(), _waiters.end());
    _waiters.clear();
  }
}

inline size_t Semaphore::max_value() const {
  return _max_value; 
}

inline size_t Semaphore::value() const {
  std::lock_guard<std::mutex> lock(_mtx);
  return _cur_value;
}

inline void Semaphore::reset() {
  std::lock_guard<std::mutex> lock(_mtx);
  _cur_value = _max_value;
  _waiters.clear();
}

inline void Semaphore::reset(size_t new_max_value) {
  std::lock_guard<std::mutex> lock(_mtx);
  _cur_value = (_max_value = new_max_value);
  _waiters.clear();
}

class NonblockingNotifier {

  friend class Executor;

  struct Waiter {
    alignas (TF_CACHELINE_SIZE) std::atomic<Waiter*> next;
    uint64_t epoch;

    enum : unsigned {
      kNotSignaled = 0,
      kWaiting,
      kSignaled,
    };
    std::atomic<unsigned> state {0};

    //mutable std::mutex mu;
    //std::condition_variable cv;
    //unsigned state;
  };

  public:

  static const uint64_t STACK_BITS = 16;
  static const uint64_t STACK_MASK = (1ull << STACK_BITS) - 1;
  static const uint64_t PREWAITER_BITS = 16;
  static const uint64_t PREWAITER_SHIFT = 16;
  static const uint64_t PREWAITER_MASK = ((1ull << PREWAITER_BITS) - 1) << PREWAITER_SHIFT;
  static const uint64_t PREWAITER_INC = 1ull << PREWAITER_BITS;
  static const uint64_t EPOCH_BITS = 32;
  static const uint64_t EPOCH_SHIFT = 32;
  static const uint64_t EPOCH_MASK = ((1ull << EPOCH_BITS) - 1) << EPOCH_SHIFT;
  static const uint64_t EPOCH_INC = 1ull << EPOCH_SHIFT;

  explicit NonblockingNotifier(size_t N) : _state(STACK_MASK), _waiters(N) {
    if(_waiters.size() >= ((1 << PREWAITER_BITS) - 1)) {
      TF_THROW("nonblocking waiter supports only up to ", (1<<PREWAITER_BITS)-1, " waiters");
    }
  }

  ~NonblockingNotifier() {
    assert((_state.load() & (STACK_MASK | PREWAITER_MASK)) == STACK_MASK);
  }

  size_t num_waiters() const {
    size_t n = 0;
    for(auto& w : _waiters) {
      n += (w.state.load(std::memory_order_relaxed) == Waiter::kWaiting);
    }
    return n;
  }

  size_t capacity() const {
    return 1 << STACK_BITS;
  }

  void prepare_wait(size_t wid) {
    _waiters[wid].epoch = _state.fetch_add(PREWAITER_INC, std::memory_order_relaxed);
    std::atomic_thread_fence(std::memory_order_seq_cst);
  }

  void commit_wait(size_t wid) {

    auto w = &_waiters[wid];

    w->state.store(Waiter::kNotSignaled, std::memory_order_relaxed);

    uint64_t epoch =
        (w->epoch & EPOCH_MASK) +
        (((w->epoch & PREWAITER_MASK) >> PREWAITER_SHIFT) << EPOCH_SHIFT);
    uint64_t state = _state.load(std::memory_order_seq_cst);
    for (;;) {
      if (int64_t((state & EPOCH_MASK) - epoch) < 0) {
        std::this_thread::yield();
        state = _state.load(std::memory_order_seq_cst);
        continue;
      }
      if (int64_t((state & EPOCH_MASK) - epoch) > 0) {
        return;
      }
      assert((state & PREWAITER_MASK) != 0);
      uint64_t newstate = state - PREWAITER_INC + EPOCH_INC;
      newstate = (newstate & ~STACK_MASK) | wid;

      if ((state & STACK_MASK) == STACK_MASK) {
        w->next.store(nullptr, std::memory_order_relaxed);
      }
      else {
        w->next.store(&_waiters[state & STACK_MASK], std::memory_order_relaxed);
      }
      if (_state.compare_exchange_weak(state, newstate, std::memory_order_release)) {
        break;
      }
    }
    _park(w);
  }

  void cancel_wait(size_t wid) {
    uint64_t epoch =
      (_waiters[wid].epoch & EPOCH_MASK) +
      (((_waiters[wid].epoch & PREWAITER_MASK) >> PREWAITER_SHIFT) << EPOCH_SHIFT);
    uint64_t state = _state.load(std::memory_order_relaxed);
    for (;;) {
      if (int64_t((state & EPOCH_MASK) - epoch) < 0) {
        std::this_thread::yield();
        state = _state.load(std::memory_order_relaxed);
        continue;
      }
      if (int64_t((state & EPOCH_MASK) - epoch) > 0) {
        return;
      }
      assert((state & PREWAITER_MASK) != 0);
      if (_state.compare_exchange_weak(state, state - PREWAITER_INC + EPOCH_INC,
                                       std::memory_order_relaxed)) {
        return;
      }
    }
  }

  void notify_one() {
    std::atomic_thread_fence(std::memory_order_seq_cst);
    uint64_t state = _state.load(std::memory_order_acquire);
    for (;;) {
      if ((state & STACK_MASK) == STACK_MASK && (state & PREWAITER_MASK) == 0) {
        return;
      }
      uint64_t num_prewaiters = (state & PREWAITER_MASK) >> PREWAITER_SHIFT;
      uint64_t newstate;
      if (num_prewaiters) {
        newstate = state + EPOCH_INC - PREWAITER_INC;
      } 
      else {
        Waiter* w = &_waiters[state & STACK_MASK];
        Waiter* wnext = w->next.load(std::memory_order_relaxed);
        uint64_t next = STACK_MASK;
        if (wnext != nullptr) {
          next = static_cast<uint64_t>(wnext - &_waiters[0]);
        }
        newstate = (state & EPOCH_MASK) + next;
      }
      if (_state.compare_exchange_weak(state, newstate, std::memory_order_acquire)) {
        if(num_prewaiters) {
          return;
        }
        Waiter* w = &_waiters[state & STACK_MASK];
        w->next.store(nullptr, std::memory_order_relaxed);
        _unpark(w);
        return;
      }
    }
  }

  void notify_all() {
    std::atomic_thread_fence(std::memory_order_seq_cst);
    uint64_t state = _state.load(std::memory_order_acquire);
    for (;;) {

      if ((state & STACK_MASK) == STACK_MASK && (state & PREWAITER_MASK) == 0) {
        return;
      }
      uint64_t num_prewaiters = (state & PREWAITER_MASK) >> PREWAITER_SHIFT;

      uint64_t newstate = (state & EPOCH_MASK) + (EPOCH_INC * num_prewaiters) + STACK_MASK;

      if (_state.compare_exchange_weak(state, newstate, std::memory_order_acquire)) {
        if ((state & STACK_MASK) == STACK_MASK) {
          return;
        }
        Waiter* w = &_waiters[state & STACK_MASK];
        _unpark(w);
        return;
      }
    }
  }

  void notify_n(size_t N) {

    if(N == 0) {
      return;
    }

    if(N >= _waiters.size()) {
      notify_all();
      return;
    }

    std::atomic_thread_fence(std::memory_order_seq_cst);
    uint64_t state = _state.load(std::memory_order_acquire);
    do {
      if ((state & STACK_MASK) == STACK_MASK && (state & PREWAITER_MASK) == 0) {
        return;
      }
      uint64_t num_prewaiters = (state & PREWAITER_MASK) >> PREWAITER_SHIFT;
      uint64_t newstate;
      size_t   newN;

      if(num_prewaiters) {
        size_t to_unblock = (N < num_prewaiters) ? N : num_prewaiters;
        newstate = state + (EPOCH_INC * to_unblock) - (PREWAITER_INC * to_unblock);
        newN = N - to_unblock;
      }
      else {
        Waiter* w = &_waiters[state & STACK_MASK];
        Waiter* wnext = w->next.load(std::memory_order_relaxed);
        uint64_t next = STACK_MASK;
        if (wnext != nullptr) {
          next = static_cast<uint64_t>(wnext - &_waiters[0]);
        }
        newstate = (state & EPOCH_MASK) + next;
        newN = N - 1;
      }

      if (_state.compare_exchange_weak(state, newstate, std::memory_order_acquire)) {
        N = newN;
        if(num_prewaiters == 0) {
          Waiter* w = &_waiters[state & STACK_MASK];
          w->next.store(nullptr, std::memory_order_relaxed);
          _unpark(w);
        }
      }
    } while(N > 0);
  }

  size_t size() const {
    return _waiters.size();
  }

 private:

  std::atomic<uint64_t> _state;
  std::vector<Waiter> _waiters;

  void _park(Waiter* w) {
    unsigned target = Waiter::kNotSignaled;
    if(w->state.compare_exchange_strong(target, Waiter::kWaiting, std::memory_order_relaxed
                                                                , std::memory_order_relaxed)) {
      w->state.wait(Waiter::kWaiting, std::memory_order_relaxed);
    }
  }

  void _unpark(Waiter* waiters) {
    Waiter* next = nullptr;
    for (Waiter* w = waiters; w; w = next) {
      next = w->next.load(std::memory_order_relaxed);
      if(w->state.exchange(Waiter::kSignaled, std::memory_order_relaxed) == Waiter::kWaiting) {
        w->state.notify_one();
      }
    }
  }
};

class AtomicNotifier {

  friend class Executor;

  public:

  struct Waiter {
    alignas (2*TF_CACHELINE_SIZE) uint32_t epoch;
  };

  AtomicNotifier(size_t N) noexcept : _state(0), _waiters(N) {}
  ~AtomicNotifier() { assert((_state.load() & WAITER_MASK) == 0); } 

  void notify_one() noexcept;
  void notify_all() noexcept;
  void notify_n(size_t) noexcept;
  void prepare_wait(size_t) noexcept;
  void cancel_wait(size_t) noexcept;
  void commit_wait(size_t) noexcept;

  size_t size() const noexcept;
  size_t num_waiters() const noexcept;

 private:

  AtomicNotifier(const AtomicNotifier&) = delete;
  AtomicNotifier(AtomicNotifier&&) = delete;
  AtomicNotifier& operator=(const AtomicNotifier&) = delete;
  AtomicNotifier& operator=(AtomicNotifier&&) = delete;

  // This requires 64-bit
  static_assert(sizeof(int) == 4, "bad platform");
  static_assert(sizeof(uint32_t) == 4, "bad platform");
  static_assert(sizeof(uint64_t) == 8, "bad platform");
  static_assert(sizeof(std::atomic<uint64_t>) == 8, "bad platform");

  // _state stores the epoch in the most significant 32 bits and the
  // waiter count in the least significant 32 bits.
  std::atomic<uint64_t> _state;
  std::vector<Waiter> _waiters;

  static constexpr uint64_t WAITER_INC  {1};
  static constexpr uint64_t EPOCH_SHIFT {32};
  static constexpr uint64_t EPOCH_INC   {uint64_t(1) << EPOCH_SHIFT};
  static constexpr uint64_t WAITER_MASK {EPOCH_INC - 1};
};

inline size_t AtomicNotifier::size() const noexcept {
  return _waiters.size();
}

inline size_t AtomicNotifier::num_waiters() const noexcept {
  return _state.load(std::memory_order_relaxed) & WAITER_MASK;
}

inline void AtomicNotifier::notify_one() noexcept {
  std::atomic_thread_fence(std::memory_order_seq_cst);
  for(uint64_t state = _state.load(std::memory_order_relaxed); state & WAITER_MASK;) {
    if(_state.compare_exchange_weak(state, state + EPOCH_INC, std::memory_order_relaxed)) {
      _state.notify_one(); 
      break;
    }
  }
}

inline void AtomicNotifier::notify_all() noexcept {
  std::atomic_thread_fence(std::memory_order_seq_cst);
  for(uint64_t state = _state.load(std::memory_order_relaxed); state & WAITER_MASK;) {
    if(_state.compare_exchange_weak(state, state + EPOCH_INC, std::memory_order_relaxed)) {
      _state.notify_all(); 
      break;
    }
  }
}

inline void AtomicNotifier::notify_n(size_t n) noexcept {
  if(n >= _waiters.size()) {
    notify_all();
  }
  else {
    for(size_t k=0; k<n; ++k) {
      notify_one();
    }
  }
}

inline void AtomicNotifier::prepare_wait(size_t w) noexcept {
  auto prev = _state.fetch_add(WAITER_INC, std::memory_order_relaxed);
  _waiters[w].epoch = (prev >> EPOCH_SHIFT);
  std::atomic_thread_fence(std::memory_order_seq_cst);
}

inline void AtomicNotifier::cancel_wait(size_t) noexcept {
  _state.fetch_sub(WAITER_INC, std::memory_order_relaxed);
}

inline void AtomicNotifier::commit_wait(size_t w) noexcept {
  uint64_t prev = _state.load(std::memory_order_relaxed);
  while((prev >> EPOCH_SHIFT) == _waiters[w].epoch) {
    _state.wait(prev, std::memory_order_relaxed); 
    prev = _state.load(std::memory_order_relaxed);
  }
  _state.fetch_sub(WAITER_INC, std::memory_order_relaxed);
}

struct Waiter {
    alignas (2*TF_CACHELINE_SIZE) uint32_t epoch;
  };

struct NSTATE {

  using underlying_type = int;

  // scheduler state bits
  constexpr static underlying_type NONE                = 0x00000000;  
  constexpr static underlying_type CONDITIONED         = 0x10000000;  
  constexpr static underlying_type PREEMPTED           = 0x20000000;  
  constexpr static underlying_type RETAIN_SUBFLOW      = 0x40000000;
  constexpr static underlying_type JOINED_SUBFLOW      = 0x80000000;

  // exception state bits
  constexpr static underlying_type IMPLICITLY_ANCHORED = 0x01000000;

  // mask to isolate state bits - non-state bits store # weak dependents
  constexpr static underlying_type MASK                = 0xFF000000;
};

struct ESTATE {

  using underlying_type = int;  

  constexpr static underlying_type NONE                = 0x00000000; 

  // Exception state:
  // Explicit anchor needs to be in estate other it can cause data race
  // due to the read/write on creating an AnchorGuard in corun with the nstate read
  // in tear_down_async. When calling corun, all async tasks may have already
  // finished and trigger tear_down_async, causing data race on reading/writing
  // the parent node's nstate.
  constexpr static underlying_type EXCEPTION           = 0x10000000;
  constexpr static underlying_type CAUGHT              = 0x20000000;
  constexpr static underlying_type CANCELLED           = 0x40000000;
  constexpr static underlying_type EXPLICITLY_ANCHORED = 0x80000000;

  // Async task state
  //constexpr static underlying_type UNFINISHED = 0x00000000;
  constexpr static underlying_type LOCKED              = 0x01000000;
  constexpr static underlying_type FINISHED            = 0x02000000;

  // mask to isolate state bits - non-state bits store # weak dependents
  constexpr static underlying_type MASK                = 0xFF000000;
};

class Topology {

  friend class Executor;
  friend class Subflow;
  friend class Runtime;
  friend class NonpreemptiveRuntime;
  friend class Node;

  template <typename T>
  friend class Future;

  public:

  Topology(Taskflow&);

  virtual ~Topology() = default;

