// Non-blocking enqueue for pointer elements; avoid enqueuing nullptr per API guidance.
{
  tf::MPMC<int*, 3> q; // cap=8
  int x = (int)(*FUZZ_PARAM(unsigned int));
  int y = x + 1;
  int* px = &x;
  int* py = &y;
  bool ok1 = q.try_enqueue(px);
  FUZZ_ASSERT(ok1 == true, "try_enqueue(pointer) should succeed on fresh queue");
  // Fill remaining capacity with non-null pointers
  for(size_t i=0; i<q.capacity()-1; ++i){
    (void)q.try_enqueue(py);
  }
  bool full_fail = !q.try_enqueue(py);
  FUZZ_ASSERT(full_fail == true, "try_enqueue(pointer) should fail when full");
}
// Validation: Verifies success on space and failure on full without enqueuing nullptr.

// Blocking enqueue for pointer elements; ensure it only runs when space exists.
{
  tf::MPMC<int*, 3> q; // cap=8
  int v = (int)(*FUZZ_PARAM(unsigned int));
  int* pv = &v;
  q.enqueue(pv); // must succeed immediately
  // Fill remaining capacity but stop before full to avoid spinning on next call
  for(size_t i=0; i<q.capacity()-1; ++i){
    q.enqueue(pv);
  }
  // Do not enqueue beyond capacity here to avoid indefinite spinning.
}
// Validation: Uses enqueue(pointer) only when space is guaranteed; covers success path.

// Non-blocking dequeue for pointer elements; nullptr indicates empty.
{
  tf::MPMC<int*, 3> q; // cap=8
