  int v = (int)(*FUZZ_PARAM(unsigned int));
  int* pv = &v;
  (void)q.try_enqueue(pv);
  int* r1 = q.try_dequeue();
  FUZZ_ASSERT(r1 != nullptr, "try_dequeue(pointer) should return non-null after enqueue");
}
