// Exercise tf::Deserializer::operator() by round-tripping a mixture of supported types.
// Requirements enforced:
// - Types are supported by the archiver; verify equality post round-trip.
{
  // Prepare input data
  int x_in = static_cast<int>(*FUZZ_PARAM(unsigned int));
  tf::TaskType tt_in = static_cast<tf::TaskType>(*FUZZ_PARAM(unsigned int) % 8);

  std::string s_in = FUZZ_PARAM_STR();
