  size_t n = static_cast<size_t>(*FUZZ_PARAM(unsigned int) % 32u);
  std::vector<int> vec_in; vec_in.reserve(n);
  const int (*rnd_arr)[32] = FUZZ_PARAM(int[32]);
  for(size_t i=0; i<n; ++i) vec_in.push_back((*rnd_arr)[i]);

  bool has_opt_in = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
  std::optional<int> oi_in; if(has_opt_in) oi_in = static_cast<int>(*FUZZ_PARAM(unsigned int));

  std::string var_str = FUZZ_PARAM_STR();
  if(var_str.size() > 256) var_str.resize(256);
  bool pick_int = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
  std::variant<int, std::string> var_in = pick_int
    ? std::variant<int, std::string>(static_cast<int>(*FUZZ_PARAM(unsigned int)))
    : std::variant<int, std::string>(var_str);

  // Serialize all inputs
  std::stringstream ss;
  tf::Serializer<std::stringstream> ser(ss);
  ser(x_in, tt_in, s_in, vec_in, oi_in, var_in);

  // Reset to beginning and deserialize into outputs
  ss.seekg(0);
  tf::Deserializer<std::stringstream> der(ss);

  int x_out{};
  tf::TaskType tt_out{tf::TaskType::UNDEFINED};
  std::string s_out;
  std::vector<int> vec_out;
  std::optional<int> oi_out;
  std::variant<int, std::string> var_out;

  der(x_out, tt_out, s_out, vec_out, oi_out, var_out);

