  FUZZ_ASSERT(s_in == s_out, "string round-trip mismatch");
  FUZZ_ASSERT(vec_in == vec_out, "vector<int> round-trip mismatch");
  FUZZ_ASSERT(oi_in.has_value() == oi_out.has_value(), "optional engagement mismatch");
  if(oi_in.has_value()) { FUZZ_ASSERT(*oi_in == *oi_out, "optional<int> value mismatch"); }
  FUZZ_ASSERT(var_in.index() == var_out.index(), "variant alternative index mismatch");
  if(var_out.index() == 0) {
    FUZZ_ASSERT(std::get<0>(var_in) == std::get<0>(var_out), "variant<int> value mismatch");
  } else {
