// Build a heterogeneous tuple and visit an index chosen by fuzz input.
// Validate call count equals 1 when idx is in range, else 0.
{
  // Tuple under test
  int a = (int)(*FUZZ_PARAM(unsigned int) % 1000u);
  std::string b = FUZZ_PARAM_STR();
  double c = (double)(*FUZZ_PARAM(unsigned int) % 10000u) / 7.0;
  auto tup = std::make_tuple(a, b, c);

  // Choose an index in [0, size+1] to cover in-range and out-of-range
  size_t raw = (size_t)(*FUZZ_PARAM(unsigned int));
  constexpr size_t TS = std::tuple_size<decltype(tup)>::value; // 3
  size_t idx = raw % (TS + 2); // values 0..4

  // Functor that can accept any element type in the tuple
  size_t called = 0;
  auto func = [&](auto& elem){
    ++called;
    using E = std::decay_t<decltype(elem)>;
    if constexpr (std::is_same_v<E, int>) {
      elem += 1;
    } else if constexpr (std::is_same_v<E, std::string>) {
      if(elem.size() < 1024) elem.push_back('\n');
    } else if constexpr (std::is_same_v<E, double>) {
      elem *= 1.0; // no-op but ensures a write
    } else {
      // Unknown element type; still counted
      (void)elem;
    }
  };

  tf::visit_tuple(func, tup, idx);

  if(idx < TS) {
    FUZZ_ASSERT(called == 1, "visit_tuple must invoke func exactly once for in-range idx");
  } else {
    FUZZ_ASSERT(called == 0, "visit_tuple must be no-op for out-of-range idx");
  }

  // Validation: The stub verifies in-range triggers exactly one invocation and out-of-range none.
  // Tuple is local; no persistent inputs/outputs required.
}

// Instantiate tf::unroll with several compile-time ranges to cover edge and normal cases.
// We collect the visited i's into local buffers to exercise the callable.
{
  // Collector for side effects; bounded to keep memory small
  auto make_collector = [](){
    struct Col {
      std::array<int, 64> buf{};
      size_t n{0};
      void add(int v){ if(n < buf.size()) buf[n++] = v; }
    };
    return Col{};
  };

  // Case 1: empty range (beg == end)
  {
    auto col = make_collector();
    tf::unroll<0, 0, 1>([&](auto i){ col.add((int)i); });
    FUZZ_ASSERT(col.n == 0, "unroll<0,0,1> must invoke f zero times");
  }

  // Case 2: simple increasing unit step
  {
    auto col = make_collector();
    tf::unroll<0, 5, 1>([&](auto i){ col.add((int)i); });
    FUZZ_ASSERT(col.n == 5, "unroll<0,5,1> must invoke f five times");
  }

  // Case 3: positive step > 1
  {
    auto col = make_collector();
    tf::unroll<2, 10, 2>([&](auto i){ col.add((int)i); });
    FUZZ_ASSERT(col.n == 4, "unroll<2,10,2> must invoke f four times (2,4,6,8)");
  }

  // Case 4: non-zero beg with unit step
  {
    auto col = make_collector();
    tf::unroll<3, 7, 1>([&](auto i){ col.add((int)i); });
    FUZZ_ASSERT(col.n == 4, "unroll<3,7,1> must invoke f four times (3..6)");
  }

  // Validation: Multiple instantiations exercise termination and step handling; all work is local,
  // no persistent inputs/outputs required.
}

// Exercise tf::make_moc with rvalues only to avoid MoC<T&> instantiations.
// Avoid copy-assignment on MoC because some specializations may not define it
// (e.g., when T is move-only). Prefer copy-construction (which Taskflow's MoC
// implements as move-from) and move operations.
{
  // Case 1: movable, copyable type (std::string) as rvalue
  std::string s = FUZZ_PARAM_STR();
  auto moc_str = tf::make_moc(std::move(s));
  // Copy-construct (expected to move underlying string from source)
  auto moc_str_copy(moc_str);
  // Move-construct and move-assign to cover move paths without relying on copy-assign
  auto moc_str_moved(std::move(moc_str_copy));
  auto moc_str_moved2 = std::move(moc_str_moved);
  (void)moc_str_moved2;

  // Case 2: move-only type (std::unique_ptr<int>) as rvalue
  int iv = (int)(*FUZZ_PARAM(unsigned int) % 1000003u);
  auto up = std::unique_ptr<int>(new int(iv));
  auto moc_up = tf::make_moc(std::move(up));
  // After moving into MoC, original unique_ptr must be empty
  FUZZ_ASSERT(up.get() == nullptr, "unique_ptr must be empty after move into make_moc");
  // Only exercise copy-construction if it is available; otherwise skip
  // (Some MoC implementations provide copy-ctor that move-from the source)
  if constexpr (std::is_copy_constructible_v<decltype(moc_up)>) {
    auto moc_up_copy(moc_up);
    (void)moc_up_copy;
  }
  // Always exercise move paths
  auto moc_up_moved(std::move(moc_up));
  auto moc_up_moved2 = std::move(moc_up_moved);
  (void)moc_up_moved2;

  // Case 3: trivially movable/copyable type (tf::UUID) as rvalue
  tf::UUID uid;  // default-constructed
  auto moc_uuid = tf::make_moc(std::move(uid));
  auto moc_uuid_copy(moc_uuid);    // copy-construct (moves from source inside MoC)
  auto moc_uuid_moved(std::move(moc_uuid_copy));
  auto moc_uuid_moved2 = std::move(moc_uuid_moved);
  (void)moc_uuid_moved2;

  // Validation: We only pass rvalues to make_moc and avoid copy-assignment on MoC.
  // For move-only payloads we assert the source unique_ptr is null after move.
}

// Construct a new UUID object on the heap and return it to the pool.
// Requirement: no inputs; object contains 16 bytes of v4 UUID data.
tf::UUID *uuid = new tf::UUID();
// Basic property: a UUID object must have 16 bytes.
FUZZ_ASSERT(tf::UUID::size() == 16, "UUID size must be 16 bytes");
// Provide uuid as persistent output.

// Call the static size() and assert the canonical size.
auto sz = tf::UUID::size();
FUZZ_ASSERT(sz == 16, "tf::UUID::size() must be 16");
// No persistent objects created or consumed.

