auto b = uuid->begin();
auto e = uuid->end();
// The range must represent exactly size() bytes and b <= e.
FUZZ_ASSERT(b <= e, "begin must be <= end");
ptrdiff_t diff = e - b;
FUZZ_ASSERT(diff == (ptrdiff_t)tf::UUID::size(), "[begin,end) must span 16 bytes");
// Return the uuid back to the pool as it remains valid.

// Obtain end iterator and validate it pairs correctly with begin().
auto b = uuid->begin();
auto e = uuid->end();
FUZZ_ASSERT(b <= e, "begin must be <= end");
ptrdiff_t diff = e - b;
FUZZ_ASSERT(diff == (ptrdiff_t)tf::UUID::size(), "[begin,end) must span 16 bytes");
// Do not dereference e; just return the uuid.

