bool ne = ((*a) != (*b));
bool eq = ((*a) == (*b));
FUZZ_ASSERT(ne != eq, "!= must be logical negation of ==");
// Return both objects.

// >= should be !(a < b).
bool ge = ((*a) >= (*b));
bool lt = ((*a) < (*b));
FUZZ_ASSERT(ge == !lt, ">= must be the negation of <");
// Return both objects.

// <= should be !(a > b).
bool le = ((*a) <= (*b));
bool gt = ((*a) > (*b));
FUZZ_ASSERT(le == !gt, "<= must be the negation of >");
